INSERT INTO flashcards (id, set_id, term, definition, order_index, fields_data) VALUES
('a1a1a1a1-0000-4a1a-8a1a-000000000001', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Le soleil brille aujourd''hui.', 'Le', 1, '{"category":"Артикли","qtype":"mc","prompt":"____ soleil brille aujourd''hui.","explanation":"«Soleil» — существительное мужского рода в ед. числе, поэтому определённый артикль le. La — женский род, les — множественное число, l'' — только перед гласной или h.","options":["Le","La","Les","L''"],"answerIndex":0,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000002', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Je voudrais une pomme.', 'une', 2, '{"category":"Артикли","qtype":"mc","prompt":"Je voudrais ____ pomme, s''il vous plaît.","explanation":"«Pomme» — женского рода, предмет неопределённый (одно из многих), значит неопределённый артикль une.","options":["un","une","des","le"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000003', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Ce sont les enfants de Marie.', 'les', 3, '{"category":"Артикли","qtype":"mc","prompt":"Ce sont ____ enfants de Marie.","explanation":"«Enfants» во множественном числе и это конкретные дети Марии → определённый артикль les.","options":["le","la","les","un"],"answerIndex":2,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000004', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'J''habite dans un appartement.', 'un', 4, '{"category":"Артикли","qtype":"mc","prompt":"J''habite dans ____ appartement.","explanation":"«Appartement» — мужской род, квартира не уточняется → неопределённый артикль un.","options":["un","une","des","le"],"answerIndex":0,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000005', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'L''école est fermée le dimanche.', 'L''', 5, '{"category":"Артикли","qtype":"mc","prompt":"____ école est fermée le dimanche.","explanation":"«École» женского рода, но начинается с гласной, поэтому артикль усекается: l''école.","options":["Le","La","L''","Les"],"answerIndex":2,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000006', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Elle achète des fleurs au marché.', 'des', 6, '{"category":"Артикли","qtype":"text","prompt":"Вставьте артикль: « Elle achète ___ fleurs au marché. » (неопр. мн.ч.)","explanation":"Множественное число неопределённого артикля (un/une) — это des: des fleurs (какие-то цветы).","options":[],"answerIndex":null,"accept":["des","elle achète des fleurs au marché"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000007', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'C''est un livre de français.', 'un', 7, '{"category":"Артикли","qtype":"text","prompt":"Вставьте артикль: « C''est ___ livre de français. » (неопр. м.р.)","explanation":"«Livre» — мужской род, предмет вводится впервые → неопределённый артикль un.","options":[],"answerIndex":null,"accept":["un","c''est un livre de français"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000008', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Je suis étudiant.', 'suis', 8, '{"category":"Глагол être","qtype":"mc","prompt":"Je ____ étudiant.","explanation":"Спряжение être: je suis, tu es, il est, nous sommes, vous êtes, ils sont.","options":["es","suis","est","sommes"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000009', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Tu es français ?', 'es', 9, '{"category":"Глагол être","qtype":"mc","prompt":"Tu ____ français ?","explanation":"Для «tu» форма être — es: tu es.","options":["es","est","suis","êtes"],"answerIndex":0,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000000a', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Il est professeur.', 'est', 10, '{"category":"Глагол être","qtype":"mc","prompt":"Il ____ professeur.","explanation":"Для «il/elle» форма être — est. После être профессия идёт без артикля.","options":["es","suis","est","sont"],"answerIndex":2,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000000b', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Nous sommes contents.', 'sommes', 11, '{"category":"Глагол être","qtype":"text","prompt":"Спряжение être: « Nous ___ contents. »","explanation":"Для «nous» форма être — sommes: nous sommes contents.","options":[],"answerIndex":null,"accept":["sommes","nous sommes contents"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000000c', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Vous êtes en retard.', 'êtes', 12, '{"category":"Глагол être","qtype":"text","prompt":"Спряжение être: « Vous ___ en retard. »","explanation":"Для «vous» форма être — êtes: vous êtes.","options":[],"answerIndex":null,"accept":["êtes","etes","vous êtes en retard"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000000d', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Elles sont amies.', 'sont', 13, '{"category":"Глагол être","qtype":"mc","prompt":"Elles ____ amies.","explanation":"«Elles» — 3-е лицо мн. числа → être = sont.","options":["est","es","sont","sommes"],"answerIndex":2,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000000e', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'J''ai vingt ans.', 'ai', 14, '{"category":"Глагол avoir","qtype":"mc","prompt":"J''____ vingt ans.","explanation":"Спряжение avoir: j''ai, tu as, il a, nous avons, vous avez, ils ont. Возраст по-французски выражается через avoir.","options":["a","ai","as","ont"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000000f', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Tu as un chien ?', 'as', 15, '{"category":"Глагол avoir","qtype":"mc","prompt":"Tu ____ un chien ?","explanation":"Для «tu» форма avoir — as: tu as.","options":["a","as","ai","avez"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000010', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Elle a une voiture.', 'a', 16, '{"category":"Глагол avoir","qtype":"mc","prompt":"Elle ____ une voiture.","explanation":"Для «il/elle» форма avoir — a: elle a.","options":["a","as","ai","ont"],"answerIndex":0,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000011', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Nous avons faim.', 'avons', 17, '{"category":"Глагол avoir","qtype":"text","prompt":"Спряжение avoir: « Nous ___ faim. »","explanation":"Для «nous» форма avoir — avons. «Голод» тоже через avoir: avoir faim.","options":[],"answerIndex":null,"accept":["avons","nous avons faim"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000012', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Ils ont deux enfants.', 'ont', 18, '{"category":"Глагол avoir","qtype":"text","prompt":"Спряжение avoir: « Ils ___ deux enfants. »","explanation":"Для «ils/elles» форма avoir — ont. Не путать с «sont» (être)!","options":[],"answerIndex":null,"accept":["ont","ils ont deux enfants"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000013', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Vous avez des questions ?', 'avez', 19, '{"category":"Глагол avoir","qtype":"mc","prompt":"Vous ____ des questions ?","explanation":"Для «vous» форма avoir — avez: vous avez.","options":["avons","avez","ont","as"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000014', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Je parle le français.', 'parle', 20, '{"category":"Глаголы -ER","qtype":"mc","prompt":"Je ____ le français. (parler)","explanation":"Глаголы на -er: -e, -es, -e, -ons, -ez, -ent. Для «je» → parle.","options":["parle","parles","parlez","parlent"],"answerIndex":0,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000015', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Tu habites à Paris.', 'habites', 21, '{"category":"Глаголы -ER","qtype":"mc","prompt":"Tu ____ à Paris. (habiter)","explanation":"Для «tu» окончание -es → habites (буква -s не читается).","options":["habite","habites","habitez","habitent"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000016', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Il aime la musique.', 'aime', 22, '{"category":"Глаголы -ER","qtype":"mc","prompt":"Il ____ la musique. (aimer)","explanation":"Для «il/elle» окончание -e → aime.","options":["aime","aimes","aimez","aiment"],"answerIndex":0,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000017', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Nous écoutons la radio.', 'écoutons', 23, '{"category":"Глаголы -ER","qtype":"text","prompt":"Поставьте глагол: « Nous ___ la radio. » (écouter)","explanation":"Для «nous» окончание -ons → écoutons.","options":[],"answerIndex":null,"accept":["écoutons","ecoutons","nous écoutons la radio"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000018', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Vous travaillez beaucoup.', 'travaillez', 24, '{"category":"Глаголы -ER","qtype":"mc","prompt":"Vous ____ beaucoup. (travailler)","explanation":"Для «vous» окончание -ez → travaillez.","options":["travaille","travailles","travaillez","travaillent"],"answerIndex":2,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000019', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Ils jouent au football.', 'jouent', 25, '{"category":"Глаголы -ER","qtype":"mc","prompt":"Ils ____ au football. (jouer)","explanation":"Для «ils/elles» окончание -ent (не читается) → jouent. Jouer à + игра.","options":["joue","joues","jouez","jouent"],"answerIndex":3,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000001a', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Elle commande un café.', 'commande', 26, '{"category":"Глаголы -ER","qtype":"text","prompt":"Поставьте глагол: « Elle ___ un café. » (commander)","explanation":"Для «elle» окончание -e → commande.","options":[],"answerIndex":null,"accept":["commande","elle commande un café"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000001b', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'sept', 'sept', 27, '{"category":"Числа","qtype":"mc","prompt":"Comment écrit-on « 7 » ?","explanation":"7 = sept. (six=6, huit=8, neuf=9).","options":["six","sept","huit","neuf"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000001c', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'quinze', '15', 28, '{"category":"Числа","qtype":"mc","prompt":"« Quinze » correspond à :","explanation":"«Quinze» = 15. (quatorze=14, seize=16, cinquante=50).","options":["14","15","16","50"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000001d', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'vingt', 'vingt', 29, '{"category":"Числа","qtype":"mc","prompt":"Comment dit-on « 20 » ?","explanation":"20 = vingt. (dix=10, douze=12, trente=30).","options":["dix","douze","vingt","trente"],"answerIndex":2,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000001e', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'cent', 'cent', 30, '{"category":"Числа","qtype":"text","prompt":"Напишите число словами по-французски: « 100 »","explanation":"100 = cent.","options":[],"answerIndex":null,"accept":["cent"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000001f', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'douze', 'douze', 31, '{"category":"Числа","qtype":"text","prompt":"Напишите число словами по-французски: « 12 »","explanation":"12 = douze.","options":[],"answerIndex":null,"accept":["douze"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000020', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'quarante', '40', 32, '{"category":"Числа","qtype":"mc","prompt":"Quel est le nombre « quarante » ?","explanation":"«Quarante» = 40. Не путать с «quatorze» (14).","options":["14","40","44","4"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000021', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Bonsoir', 'Bonsoir', 33, '{"category":"Приветствия","qtype":"mc","prompt":"Pour dire bonjour le soir, on dit :","explanation":"Вечером здороваются Bonsoir. «Bonne nuit» — спокойной ночи (перед сном).","options":["Bonjour","Bonsoir","Bonne nuit","Salut"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000022', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Merci', 'Merci', 34, '{"category":"Приветствия","qtype":"mc","prompt":"Pour remercier, on dit :","explanation":"Спасибо = Merci. «Pardon» — извинение, «s''il vous plaît» — пожалуйста.","options":["Pardon","Merci","S''il vous plaît","Au revoir"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000023', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Comment allez-vous ?', 'allez', 35, '{"category":"Приветствия","qtype":"mc","prompt":"« Comment ____-vous ? » (demander l''état)","explanation":"«Как дела?»: Comment allez-vous? — устойчивая фраза с глаголом aller.","options":["allez","êtes","avez","faites"],"answerIndex":0,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000024', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'De rien.', 'de rien', 36, '{"category":"Приветствия","qtype":"text","prompt":"Ответ на « Merci » (два слова, «не за что»):","explanation":"Стандартный вежливый ответ на «merci» — de rien («не за что»).","options":[],"answerIndex":null,"accept":["de rien"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000025', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Au revoir', 'Au revoir', 37, '{"category":"Приветствия","qtype":"mc","prompt":"Pour dire au revoir :","explanation":"«До свидания» = Au revoir.","options":["Bonjour","Merci","Au revoir","Oui"],"answerIndex":2,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000026', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Comment tu t''appelles ?', 'Comment', 38, '{"category":"Вопросы","qtype":"mc","prompt":"____ tu t''appelles ?","explanation":"«Как тебя зовут?» = Comment tu t''appelles? Comment = как.","options":["Comment","Où","Quand","Combien"],"answerIndex":0,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000027', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Où habites-tu ?', 'Où', 39, '{"category":"Вопросы","qtype":"mc","prompt":"____ habites-tu ?","explanation":"«Где ты живёшь?» = Où habites-tu? Où = где/куда.","options":["Qui","Où","Quoi","Quand"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000028', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Combien ça coûte ?', 'Combien', 40, '{"category":"Вопросы","qtype":"mc","prompt":"____ ça coûte ? (le prix)","explanation":"Цена спрашивается словом Combien (сколько).","options":["Comment","Où","Combien","Pourquoi"],"answerIndex":2,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-000000000029', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'quand', 'quand', 41, '{"category":"Вопросы","qtype":"text","prompt":"Вопросительное слово «когда» по-французски:","explanation":"«Когда» = quand.","options":[],"answerIndex":null,"accept":["quand"],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000002a', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Qui est cette femme ?', 'Qui', 42, '{"category":"Вопросы","qtype":"mc","prompt":"____ est cette femme ? (l''identité)","explanation":"О личности спрашивают Qui (кто).","options":["Qui","Où","Quand","Combien"],"answerIndex":0,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000002b', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Pourquoi tu apprends le français ?', 'Pourquoi', 43, '{"category":"Вопросы","qtype":"mc","prompt":"____ tu apprends le français ? (la raison)","explanation":"Причину спрашивают словом Pourquoi (почему). Ответ — с «parce que».","options":["Comment","Pourquoi","Où","Combien"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000002c', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'C''est mon livre.', 'mon', 44, '{"category":"Притяжательные","qtype":"mc","prompt":"C''est ____ livre. (à moi)","explanation":"«Livre» — мужской род, ед. число → mon (мой).","options":["mon","ma","mes","ton"],"answerIndex":0,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000002d', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Ma sœur est gentille.', 'Ma', 45, '{"category":"Притяжательные","qtype":"mc","prompt":"____ sœur est gentille. (à moi)","explanation":"«Sœur» — женский род, ед. число → ma (моя).","options":["Mon","Ma","Mes","Ta"],"answerIndex":1,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
('a1a1a1a1-0000-4a1a-8a1a-00000000002e', 'a1a1a1a1-0000-4a1a-8a1a-000000000001', 'Ce sont mes parents.', 'mes', 46, '{"category":"Притяжательные","qtype":"mc","prompt":"Ce sont ____ parents. (à moi)","explanation":"«Parents» — мн. число → mes (мои). Согласуется с предметом, не с владельцем.","options":["mon","ma","mes","ton"],"answerIndex":2,"accept":[],"term_audio":"__AUDIO_ON_SERVER__"}'::jsonb),
